WITH base AS (SELECT id, device_code, reading_ts, temp_c, humidity, DATE_TRUNC('year', reading_ts) AS reading_ts_period FROM device_readings WHERE reading_ts > TIMESTAMP '2025-09-01 02:00:00' AND status_bits < 10), gaps AS (SELECT *, CASE WHEN LAG(reading_ts_period) OVER (PARTITION BY device_code ORDER BY reading_ts_period ASC, id ASC) IS NULL OR reading_ts_period > LAG(reading_ts_period) OVER (PARTITION BY device_code ORDER BY reading_ts_period ASC, id ASC) + INTERVAL 60 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM base), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts_period ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT device_code, APPROX_PERCENTILE(is_new_burst, ARRAY(0.25, 0.5, 0.75)) AS is_new_burst_quartiles, SUM(CASE WHEN device_code = 'DV-01' THEN is_new_burst ELSE 0 END) AS dv_01_is_new_burst FROM islands GROUP BY device_code HAVING SUM(CASE WHEN device_code = 'DV-01' THEN is_new_burst ELSE 0 END) > 0 ORDER BY device_code ASC;
